176: function originMatchesRequest(origin: string, context: Context, security: HttpSecurityOptions): boolean {
177:   let parsed: URL;
178:   try {
179:     parsed = new URL(origin);
180:   } catch {
181:     return false;
182:   }
183:   if (security.allowedOrigins.includes(parsed.origin)) return true;
184:   const requestUrl = new URL(context.req.url);
185:   const host = context.req.header("host") ?? requestUrl.host;
186:   const forwardedProto = security.trustProxy ? context.req.header("x-forwarded-proto")?.split(",")[0]?.trim() : undefined;
187:   const protocol = forwardedProto ?? requestUrl.protocol.replace(":", "");
188:   return parsed.protocol === `${protocol}:` && parsed.host.toLowerCase() === host.toLowerCase();
189: }
