905: function engineSummary(
906:   project: Project,
907:   status: ReturnType<ConnectionService["status"]>,
908: ) {
909:   const model = project.engine.model
910:     ? `${project.engine.model.providerID}/${project.engine.model.id}${project.engine.model.variant ? `#${project.engine.model.variant}` : ""}`
911:     : null;
912:   const selected = project.engine.model;
913:   const discovered = selected
914:     ? status.discovery?.models.find((candidate) => candidate.providerID === selected.providerID && candidate.id === selected.id)
915:     : undefined;
916:   const modelAvailable = Boolean(discovered
917:     && discovered.availability === "available"
918:     && (selected?.variant ? discovered.variants.includes(selected.variant) : true)
919:     && (project.modelPreferences.access.mode === "ALL_ACCESSIBLE"
920:       || discovered.pricing === "free"
921:       || discovered.local === true));
922:   const diagnostic = status.diagnostics.find((item) => item.severity === "error")
923:     ?? status.diagnostics.find((item) => item.severity === "warning");
924:   return {
925:     available: Boolean(status.discovery) && status.state !== "incompatible_version" && status.state !== "authentication_required" && status.state !== "unavailable",
926:     state: status.state,
927:     serverVersion: status.serverVersion,
928:     model,
929:     modelAvailable,
930:     limitation: diagnostic?.message ?? null,
931:   };
932: }
