946: function connectionError(context: Context, error: unknown) {
947:   if (error instanceof ConnectionConfigError) {
948:     return context.json({
949:       code: error.code,
950:       message: error.message,
951:       retryable: error.code !== "REMOTE_HTTP_FORBIDDEN" && error.code !== "URL_CREDENTIALS_FORBIDDEN",
952:     }, 400);
953:   }
954:   if (error instanceof z.ZodError) {
955:     const providerKey = error.issues.some((issue) =>
956:       /apikey|api_key|providerkey|provider_key|token|secret/i.test(`${String(issue.path[0] ?? "")} ${issue.message}`));
957:     return context.json({
958:       code: "INVALID_REQUEST",
959:       message: providerKey
960:         ? "Provider API keys are managed inside OpenCode and are not accepted by Unfinished Business."
961:         : "Invalid OpenCode connection request.",
962:       retryable: true,
963:     }, 400);
