140:    * flight. This retries optimistic concurrency conflicts a bounded number of
141:    * times and never repeats the native operation itself.
142:    */
143:   async executeLatest(
144:     actionId: string,
145:     payload: unknown,
146:     mutation: (project: Project) => Project,
147:   ): Promise<ActionResult> {
148:     const hash = payloadHash(payload);
149:     for (let attempt = 0; attempt < 5; attempt += 1) {
150:       const loaded = await this.store.load();
151:       const existing = loaded.state.actions.find((action) => action.id === actionId);
152:       if (existing) {
153:         if (existing.payloadHash !== hash) throw new RevisionConflict("Background action ID was reused with a different payload.");
