155:       }
156:       const next = mutation(loaded.state);
157:       next.actions.push({
158:         id: actionId,
159:         payloadHash: hash,
160:         resultRevision: loaded.state.revision + 1,
161:         createdAt: this.now().toISOString(),
162:       });
163:       try {
164:         return { project: await this.store.save(loaded.state.revision, next), duplicate: false };
165:       } catch (error) {
166:         if (!(error instanceof RevisionConflict) || attempt === 4) throw error;
167:       }
168:     }
169:     throw new RevisionConflict("Background update could not be applied to the latest project revision.");
170:   }
