683: function spiritStateFor(
684:   project: WorkshopProject,
685:   section: WorkshopProject["sections"][number] | null,
686: ): SpiritState {
687:   if (project.stage === "ORACLE") {
688:     return project.product.status === "PROPOSED" ? "clarification" : "listening";
689:   }
690:   if (project.stage === "ARCHITECT") {
691:     return section && (section.status === "DRAFT" || section.status === "STALE") ? "drawing" : "approval";
692:   }
693:   if (project.stage === "MAKER") {
694:     const latest = [...project.operations].reverse().find((operation) => operation.kind === "maker");
695:     if (!latest) return "idle";
696:     if (latest.status === "WAITING_PERMISSION") return "permission";
697:     if (latest.status === "ABANDONED" || latest.status === "COMPLETED_UNAPPLIED") return "permission";
698:     if (latest.status === "FAILED" || latest.status === "CANCELLED") return "blocked";
699:     if (latest.status === "SUCCEEDED") return "success";
700:     return "building";
701:   }
702:   if (project.evidence.some((item) => item.result === "FAIL" || item.result === "INCONCLUSIVE")) return "warning";
703:   if (project.witnessDrafts.length > 0) return "evidence";
704:   return "scanning";
705: }

