104: /**
105:  * The hosted demo deliberately issues no session token. A failed token request
106:  * is not fatal for read-only requests; the server returns DEMO_READ_ONLY for
107:  * mutations before looking at the token.
108:  */
109: async function token(): Promise<string | null> {
110:   if (sessionToken) return sessionToken;
111:   if (sessionUnavailable) return null;
112:   try {
113:     const response = await fetch("/api/session");
114:     if (!response.ok) {
115:       sessionUnavailable = true;
116:       return null;
117:     }
118:     const body = await response.json() as { token: string };
119:     sessionToken = REDACTED;
120:     return sessionToken;
121:   } catch {
122:     sessionUnavailable = true;
123:     return null;
124:   }
125: }
