127: async function request<T>(path: string, init?: { method?: string; body?: unknown }): Promise<T> {
128:   const headers: Record<string, string> = {};
129:   const currentToken = await token();
130:   if (currentToken) headers["x-ub-session-token"] = currentToken;
131:   if (init?.body !== undefined) {
132:     headers["content-type"] = "application/json";
133:   }
134:   const response = await fetch(path, {
135:     method: init?.method ?? "GET",
136:     headers,
137:     body: init?.body !== undefined ? JSON.stringify(init.body) : undefined,
138:   });
139:   const body = await response.json() as T & {
140:     message?: string;
141:     code?: string;
142:     retryable?: boolean;
143:     providerError?: ProviderErrorDetails | null;
144:     requestId?: string;
145:   };
146:   if (!response.ok) {
147:     throw new ApiError(
148:       body.message ?? "The workshop could not complete that action.",
149:       body.code ?? "REQUEST_FAILED",
150:       Boolean(body.retryable),
151:       body.providerError ?? null,
152:       body.requestId ?? null,
153:     );
154:   }
155:   return body;
156: }
