13: export function runApprovedNodeCheck(workspace: string, timeoutMs = 30_000): Promise<NodeCheckResult> {
14:   return new Promise((resolve) => {
15:     const child = spawn(process.execPath, ["--test"], {
16:       cwd: workspace,
17:       shell: false,
18:       timeout: timeoutMs,
19:       killSignal: "SIGKILL",
20:       env: {
21:         PATH: process.env.PATH ?? "",
22:         HOME: process.env.HOME ?? "",
23:         NODE_ENV: "test",
24:         NO_COLOR: "1",
25:       },
26:     });
27:     let output = "";
28:     let finished = false;
29:     const append = (chunk: Buffer) => {
30:       if (output.length < 8_000) output += chunk.toString("utf8").slice(0, 8_000 - output.length);
31:     };
32:     const finish = (result: NodeCheckResult) => {
33:       if (finished) return;
34:       finished = true;
35:       resolve(result);
36:     };
37:     child.stdout.on("data", append);
38:     child.stderr.on("data", append);
39:     child.on("error", (error) => finish({ code: null, output: error.message }));
40:     child.on("close", (code, signal) => {
41:       const suffix = signal ? `Terminated by ${signal}.` : "";
42:       finish({
43:         code,
44:         output: [output.trim(), suffix].filter(Boolean).join("\n") || "The Node check produced no output.",
