40: /**
41:  * Owns the in-process half of a Maker run. Persisted operation state remains the
42:  * source of truth across process restarts; an interrupted process leaves a
43:  * reconciled ABANDONED record rather than silently replaying the native action.
44:  */
45: export class MakerRunCoordinator {
46:   private readonly activeRuns = new Map<string, ActiveRun>();
47: 
48:   constructor(
49:     private readonly options: {
50:       workflow: WorkflowService;
51:       guide: SpiritGuide;
52:       demoWorkspace: string;
53:       nodeCheckTimeoutMs?: number;
54:     },
55:   ) {}
56: 
57:   start(input: MakerRunInput): void {
58:     if (this.activeRuns.has(input.operationId)) return;
59:     const active: ActiveRun = { sessionId: input.sessionId, cancelled: false };
60:     this.activeRuns.set(input.operationId, active);
61:     void this.execute(input, active)
62:       .catch(async (error) => {
63:         await this.markFailed(input.operationId, error, input.model, input.agent).catch(() => undefined);
64:       })
65:       .finally(() => {
66:         this.activeRuns.delete(input.operationId);
67:       });
68:   }
69: 
70:   active(operationId: string): { sessionId: string | null } | null {
71:     const found = this.activeRuns.get(operationId);
72:     return found ? { sessionId: found.sessionId } : null;
73:   }
74: 
75:   markCancelled(operationId: string): void {
76:     const found = this.activeRuns.get(operationId);
77:     if (found) found.cancelled = true;
78:   }
79: 
80:   async markFailed(operationId: string, error: unknown, model: ModelRef, agent: string | null): Promise<void> {
81:     const sessionId = typeof (error as { nativeSessionId?: unknown })?.nativeSessionId === "string"
82:       ? (error as { nativeSessionId: string }).nativeSessionId
83:       : null;
84:     const providerFailure = providerErrorFor(error, model.providerID, sessionId);
85:     const message = providerFailure?.whatHappened ?? (error instanceof Error ? error.message : "The Maker run could not start.");
86:     await this.finish(operationId, {
87:       status: failureIsUncertain(message, error) ? "ABANDONED" : "FAILED",
88:       result: message,
89:       model,
90:       agent,
91:       sessionId,
92:       diff: null,
93:       check: null,
94:       providerError: providerFailure,
95:     });
96:   }
97: 
98:   private async execute(input: MakerRunInput, active: ActiveRun): Promise<void> {
99:     const startedAt = new Date().toISOString();
100:     await this.update(input, "start", (project) => {
101:       const next = structuredClone(project);
102:       const operation = next.operations.find((item) => item.id === input.operationId);
103:       if (operation && operation.status === "QUEUED") {
104:         operation.status = "RUNNING";
105:         operation.startedAt ??= startedAt;
106:         operation.result = `Running in OpenCode with ${modelLabel(input.model)}.`;
107:       }
108:       return refreshNextAction(next);
109:     });
110: 
111:     try {
112:       const performed = await this.options.guide.perform({
113:         role: "maker",
114:         conversationId: input.projectId,
115:         sessionId: input.sessionId,
116:         prompt: input.prompt,
117:         workspace: input.workspace,
118:         model: input.model,
119:         agent: input.agent,
120:         budget: input.budget,
121:         onSession: (sessionId) => {
122:           active.sessionId = sessionId;
123:           void this.update(input, "session", (project) => {
124:             const next = structuredClone(project);
125:             const operation = next.operations.find((item) => item.id === input.operationId);
126:             if (operation) {
127:               operation.nativeSessionId = sessionId;
128:               operation.result = `Running in OpenCode session ${sessionId}.`;
129:             }
130:             rememberSession(next, "maker", sessionId);
131:             return refreshNextAction(next);
132:           }).catch(() => {
133:             // The completion update retries against the latest revision. A
134:             // failed intermediate write is recoverable and never repeats work.
135:           });
136:         },
137:       });
138:       active.sessionId = performed.sessionId;
139: 
140:       if (active.cancelled) {
141:         await this.finish(input.operationId, {
142:           status: "CANCELLED",
143:           result: "Cancellation was recorded before the native run finished.",
144:           model: input.model,
145:           agent: input.agent,
146:           sessionId: performed.sessionId,
147:           diff: performed.diff,
148:           check: null,
149:           messageId: performed.messageId,
150:           providerError: null,
151:         });
152:         return;
153:       }
154: 
155:       if (performed.pendingPermission) {
156:         await this.finish(input.operationId, {
157:           status: "WAITING_PERMISSION",
158:           result: "A native permission request is pending. Resolve it in OpenCode, then reconcile. The run was not repeated.",
159:           model: input.model,
160:           agent: input.agent,
161:           sessionId: performed.sessionId,
162:           diff: performed.diff,
163:           check: null,
164:           messageId: performed.messageId,
165:           providerError: null,
166:         });
167:         return;
168:       }
