173:         await this.finish(input.operationId, {
174:           status: "ABANDONED",
175:           result: "The native Maker run did not become idle before the deadline. It was not repeated; reconcile before another run.",
176:           model: input.model,
177:           agent: input.agent,
178:           sessionId: performed.sessionId,
179:           diff: performed.diff,
180:           check: null,
181:           messageId: performed.messageId,
182:           providerError: null,
183:         });
184:         return;
