193:         status: edited ? "SUCCEEDED" : "FAILED",
194:         result: performed.diff,
195:         model: input.model,
196:         agent: input.agent,
197:         sessionId: performed.sessionId,
198:         diff: performed.diff,
199:         check,
200:         messageId: performed.messageId,
201:         providerError: null,
202:       });
203:     } catch (error) {
204:       const message = error instanceof Error ? error.message : "The native Maker run failed.";
205:       const errorSessionId = typeof (error as { nativeSessionId?: unknown })?.nativeSessionId === "string"
