207:         : null;
208:       const providerFailure = providerErrorFor(error, input.model.providerID, errorSessionId ?? active.sessionId);
209:       const safeMessage = providerFailure?.whatHappened ?? message;
210:       await this.finish(input.operationId, {
211:         status: active.cancelled ? "CANCELLED" : failureIsUncertain(message, error) ? "ABANDONED" : "FAILED",
212:         result: active.cancelled
213:           ? "Cancellation was recorded before the native run finished."
214:           : failureIsUncertain(message, error)
215:             ? `Disconnected or interrupted: ${safeMessage}. Reconcile the native session before another run.`
216:             : safeMessage,
217:         model: input.model,
218:         agent: input.agent,
219:         sessionId: errorSessionId ?? active.sessionId,
220:         diff: null,
221:         check: null,
222:         providerError: providerFailure,
223:       });
224:     }
225:   }
