227:   private async finish(
228:     operationId: string,
229:     outcome: {
230:       status: "SUCCEEDED" | "FAILED" | "CANCELLED" | "ABANDONED" | "WAITING_PERMISSION";
231:       result: string;
232:       model: ModelRef;
233:       agent: string | null;
234:       sessionId: string | null;
235:       diff: string | null;
236:       check: Awaited<ReturnType<typeof runApprovedNodeCheck>> | null;
237:       messageId?: string | null;
238:       providerError: ProviderErrorDetails | null;
239:     },
240:   ): Promise<void> {
241:     await this.options.workflow.executeLatest(`run:${operationId}:finish`, { operationId, status: outcome.status }, (project) => {
242:       const next = structuredClone(project);
243:       const operation = next.operations.find((item) => item.id === operationId);
244:       if (!operation) return refreshNextAction(next);
245:       if (operation.status === "CANCELLED") {
246:         operation.result = outcome.diff
247:           ? `Cancellation was recorded. Native result after cancellation: ${outcome.diff}`
248:           : operation.result;
249:         operation.finishedAt ??= new Date().toISOString();
250:         return refreshNextAction(next);
251:       }
252:       operation.status = outcome.status;
253:       operation.model = outcome.model;
254:       operation.agent = outcome.agent;
255:       operation.nativeSessionId = outcome.sessionId ?? operation.nativeSessionId;
256:       operation.nativeMessageId = outcome.messageId ?? operation.nativeMessageId;
257:       operation.finishedAt = outcome.status === "WAITING_PERMISSION" || outcome.status === "ABANDONED"
258:         ? null
259:         : new Date().toISOString();
260:       operation.statusReason = outcome.providerError?.category.toLowerCase()
261:         ?? (outcome.status === "ABANDONED" ? "native-outcome-unconfirmed" : null);
262:       operation.lastObservedAt = new Date().toISOString();
263:       operation.appliedAt = outcome.status === "SUCCEEDED" ? operation.lastObservedAt : null;
264:       operation.providerError = outcome.providerError;
265:       const checkText = outcome.check
266:         ? `Node check exit ${outcome.check.code ?? "unavailable"}. ${outcome.check.output}`
267:         : "No native diff, so the Node check did not run.";
268:       operation.result = outcome.check ? `${outcome.result}\n\n${checkText}` : outcome.result;
269:       if (outcome.sessionId) rememberSession(next, "maker", outcome.sessionId);
270:       if (outcome.check) {
271:         next.evidence.push({
272:           id: randomUUID(),
273:           checkId: "CK-06",
274:           nativeResultReference: outcome.sessionId ?? "native-session-unavailable",
275:           testedFingerprint: payloadHash(outcome.check.output),
276:           result: outcome.check.code === 0 ? "PASS" : "FAIL",
277:           observedAt: new Date().toISOString(),
278:           limitation: outcome.check.code === 0 ? null : "The native edit did not leave a passing Node test.",
279:           model: outcome.model,
280:         });
281:         const capability = next.capabilities.find((item) => item.id === "node-check");
282:         if (capability) {
283:           capability.availability = "available";
284:           capability.observedOutcome = outcome.check.code === 0 ? "PASS" : "FAIL";
285:         }
286:         const inspection = next.capabilities.find((item) => item.id === "inspect-changes");
287:         if (inspection) {
288:           inspection.availability = "available";
289:           inspection.observedOutcome = outcome.diff;
290:         }
291:       }
292:       rememberTranscript(
293:         next,
294:         "maker",
295:         outcome.status === "SUCCEEDED"
296:           ? `${outcome.diff ?? "Maker completed."} (${modelLabel(outcome.model)})`
297:           : `${outcome.result} (${modelLabel(outcome.model)})`,
298:       );
299:       return refreshNextAction(next);
300:     });
301:   }
302: 
303:   private async update(input: MakerRunInput, phase: string, mutation: (project: Project) => Project): Promise<void> {
304:     await this.options.workflow.executeLatest(`run:${input.operationId}:${phase}`, { operationId: input.operationId, phase }, mutation);
305:   }
306: }
