308: function providerErrorFor(error: unknown, provider: string, sessionReference: string | null): ProviderErrorDetails | null {
309:   const code = typeof (error as { code?: unknown })?.code === "string" ? (error as { code: string }).code : "";
310:   if ([
311:     "BUDGET_EXCEEDED",
312:     "NATIVE_TIMEOUT",
313:     "MODEL_CHANGED",
314:     "EMPTY_RESPONSE",
315:     "ENGINE_UNAVAILABLE",
316:     "ENGINE_INCOMPATIBLE",
317:     "ENGINE_AUTH",
318:   ].includes(code)) return null;
319:   if (!isProviderFailureCandidate(error)) return null;
320:   return classifyProviderError(error, {
321:     provider,
322:     sessionReference,
323:     savedWorkChanged: sessionReference ? "possibly" : "no",
324:   }).details;
325: }

